"""Generate original compact font and bevelled game tiles without external assets."""
from pathlib import Path
chars='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789:!+-'
patterns=[
'01110/10001/10001/11111/10001/10001/10001','11110/10001/10001/11110/10001/10001/11110','01111/10000/10000/10000/10000/10000/01111','11110/10001/10001/10001/10001/10001/11110','11111/10000/10000/11110/10000/10000/11111','11111/10000/10000/11110/10000/10000/10000','01111/10000/10000/10111/10001/10001/01110','10001/10001/10001/11111/10001/10001/10001','11111/00100/00100/00100/00100/00100/11111','00111/00010/00010/00010/10010/10010/01100','10001/10010/10100/11000/10100/10010/10001','10000/10000/10000/10000/10000/10000/11111','10001/11011/10101/10101/10001/10001/10001','10001/11001/10101/10011/10001/10001/10001','01110/10001/10001/10001/10001/10001/01110','11110/10001/10001/11110/10000/10000/10000','01110/10001/10001/10001/10101/10010/01101','11110/10001/10001/11110/10100/10010/10001','01111/10000/10000/01110/00001/00001/11110','11111/00100/00100/00100/00100/00100/00100','10001/10001/10001/10001/10001/10001/01110','10001/10001/10001/10001/10001/01010/00100','10001/10001/10001/10101/10101/11011/10001','10001/10001/01010/00100/01010/10001/10001','10001/10001/01010/00100/00100/00100/00100','11111/00001/00010/00100/01000/10000/11111',
'01110/10001/10011/10101/11001/10001/01110','00100/01100/00100/00100/00100/00100/01110','01110/10001/00001/00010/00100/01000/11111','11110/00001/00001/01110/00001/00001/11110','00010/00110/01010/10010/11111/00010/00010','11111/10000/10000/11110/00001/00001/11110','01110/10000/10000/11110/10001/10001/01110','11111/00001/00010/00100/01000/01000/01000','01110/10001/10001/01110/10001/10001/01110','01110/10001/10001/01111/00001/00001/01110','00000/00100/00100/00000/00100/00100/00000','00100/00100/00100/00100/00100/00000/00100','00000/00100/00100/11111/00100/00100/00000','00000/00000/00000/11111/00000/00000/00000']
tiles=[[[0]*8 for _ in range(8)]]
tiles.append([[1 if x in (0,7) or y in (0,7) else 2 for x in range(8)] for y in range(8)])
tiles.append([[1 if x in (1,6) or y in (1,6) else 0 for x in range(8)] for y in range(8)])
for i in range(7):
    tiles.append([[3 if x in (0,7) or y in (0,7) else (1 if x==1 or y==1 else (3 if x==6 or y==6 else (2 if (x+y+i)%4 else 1))) for x in range(8)] for y in range(8)])
while len(tiles)<16: tiles.append([[0]*8 for _ in range(8)])
for pattern in patterns:
    rows=pattern.split('/')
    tiles.append([[3 if 1<=x<=5 and y<7 and rows[y][x-1]=='1' else 0 for x in range(8)] for y in range(8)])
data=[]
for tile in tiles:
    for row in tile:
        data += [sum((p&1)<<(7-x) for x,p in enumerate(row)),sum(((p>>1)&1)<<(7-x) for x,p in enumerate(row))]
Path(__file__).resolve().parents[1].joinpath('src/art.h').write_text('/* Original generated tiles. */\nstatic const unsigned char art[] = {\n'+','.join(map(str,data))+'\n};\n#define TILE_COUNT '+str(len(tiles))+'\n')
